python3 -c "import pandas as pd; 
df = pd.read_csv('data/housing_dataset.csv'); 
# Encode categorical features
categorical_cols = ['mainroad', 'guestroom', 'basement', 'hotwaterheating', 'airconditioning', 'prefarea', 'furnishingstatus']; 
for col in categorical_cols: df[col] = df[col].map({'yes': 1, 'no': 0}); 

# Correlation of numeric features with price
correlations = df.corr()['price'].sort_values(ascending=False); 
print('Correlations with Price (Numeric/Encoded):'); \
for index, value in correlations.items(): print(f'{index}: {value:.4f}'); 

# Impact of key features on average price
amenities = ['mainroad', 'guestroom', 'basement', 'hotwaterheating', 'airconditioning']; 
for amenity in amenities: 
    means = df.groupby(amenity)['price'].mean(); 
    print(f'\nMean Price by {amenity}:'); \
    print(means)"

